export const CATALOGUE: Record<string, string> = {
  "audio/filter/eq3/module.yaml":
    "# EQ 3 bandes  [audioEffect] — l'égaliseur de tranche d'une table de mixage DJ.\n#\n# Pas de jsdsp : le moteur héberge déjà l'égaliseur 4 bandes de Tracktion (`4bandEq`), avec\n# des filtres en plateau et en cloche à coefficients calculés. Ce module est un NOM et des\n# DÉFAUTS par-dessus, exactement comme `audio/utility/pitch-shift` l'est sur le Pitch Shifter.\n#\n# Trois bandes exposées sur les quatre : le second médium (`Mid gain 2`) reste à plat. Une\n# tranche DJ a trois potards, et en offrir un quatrième que le pupitre ne dessine pas ferait\n# une commande accessible seulement par le fichier.\n#\n# Les fréquences sont posées ici parce que les défauts de Tracktion sont ceux d'un EQ de\n# MASTERING, pas d'une tranche : 80 Hz / 3 kHz / 17 kHz. Un plateau haut à 17 kHz ne touche\n# que l'air — tourner un potard « aigus » n'y ferait presque rien. Les valeurs ci-dessous sont\n# les points de coupure d'une table : le grave prend le kick et la basse, le médium la voix et\n# la caisse claire, l'aigu les cymbales et l'attaque.\nextends: \"@engine/equaliser\"\nparams:\n  # Les trois gains, à plat. 0 dB est la position neutre d'un potard d'EQ.\n  Low-shelf gain: 0\n  Mid gain 1: 0\n  High-shelf gain: 0\n  # …et les points de coupure, qui ne sont pas des commandes : ce sont eux qui font que ce\n  # module est une tranche DJ plutôt qu'un EQ 4 bandes générique.\n  Low-shelf freq: 200\n  Mid freq 1: 1000\n  High-shelf freq: 6000\n  # Le quatrième filtre, neutralisé par son gain. Sa fréquence n'a plus d'importance.\n  Mid gain 2: 0\n# En un paragraphe : l'EQ d'une tranche — grave, médium, aigu, en décibels, à plat au centre.\n# Plateau bas à 200 Hz, cloche à 1 kHz, plateau haut à 6 kHz : les coupures d'une table de\n# mixage et non celles d'un EQ de mastering. La plage est celle du plugin, ±20 dB — une table\n# coupe plus qu'elle ne remonte, ce qui est un usage et non une limite.\n#\n# (C'était un `docs:`, que seul le panneau Docs affichait. Le champ n'existe plus : une note\n# est un module doc sur le graphe, et la description d'un module est son en-tête, ici.)\n",
  "audio/filter/eq3/ui.yaml":
    "# panel for audio/filter/eq3\n#\n# Trois potards et rien d'autre. Les fréquences de coupure sont dans module.yaml et n'ont\n# pas de widget : ce sont elles qui définissent CE QU'EST une bande, donc les déplacer ferait\n# un autre module plutôt qu'un autre réglage — et une tranche de table n'offre pas ce bouton.\n#\n# ±20 dB est la plage du plugin, reprise telle quelle plutôt que resserrée. Le neutre tombe\n# ainsi exactement au centre de la course, ce qu'un potard d'EQ doit faire : un potard dont le\n# 0 dB n'est pas au milieu se lit de travers à chaque coup d'œil. Une table coupe plus qu'elle\n# ne remonte — mais par l'usage, pas parce que la commande le lui interdit.\ncols: 3\nrows: 1\nwidgets:\n  low:\n    { type: knob, col: 0, row: 0, label: Grave, bind: \"Low-shelf gain\", min: -20, max: 20, step: 0.1 }\n  mid:\n    { type: knob, col: 1, row: 0, label: Médium, bind: \"Mid gain 1\", min: -20, max: 20, step: 0.1 }\n  high:\n    { type: knob, col: 2, row: 0, label: Aigu, bind: \"High-shelf gain\", min: -20, max: 20, step: 0.1 }\n",
  "audio/filter/moogladder/dsp.dsp":
    "// dsp.dsp — le passe-bas en échelle de Moog, en Faust. La source que le moteur compile :\n// deux réglages, un filtre par canal, et rien d'autre. Voir module.yaml à côté, et\n// packages/song/docs/faustModules.md pour ce que le moteur en fait.\n\nimport(\"stdfaust.lib\");\n\n// `si.smoo` lisse le saut d'un potard entre deux blocs — le zipper que `glide` évite côté\n// @studio/dsp, ici en une seule fonction de la bibliothèque standard.\ncutoff = hslider(\"Cutoff\", 1200, 20, 20000, 1) : si.smoo;\nres    = hslider(\"Res\", 0.3, 0, 0.95, 0.01) : si.smoo;\n\n// Deux instances plutôt qu'une : un module est stéréo, et les deux voies ne partagent aucun\n// état. C'est ce que `par` dit, et c'est aussi ce que le moteur attend d'un module audio.\nprocess = par(i, 2, ve.moog_vcf(res, cutoff));\n",
  "audio/filter/moogladder/module.yaml":
    "# Moog Ladder [audioEffect] — le passe-bas quatre pôles résonant, celui des synthés Moog :\n# 24 dB par octave, et une résonance qui chante puis s'auto-oscille juste avant le haut de course.\n#\n# Sa DSP est décrite dans dsp.dsp à côté, en Faust, et c'est le MOTEUR qui la compile — à la\n# différence d'un module jsdsp, dont le JS tourne ici et n'envoie qu'une description. Les deux\n# écritures sont voisines et ne diffèrent qu'en cela : voir packages/song/docs/faustModules.md.\nplugin:\n  type: faust\n  name: Moog Ladder\nparams:\n  # Les noms sont ceux des hslider() de dsp.dsp, et rien ne le vérifie de ce côté-ci : c'est le\n  # compilateur du moteur qui déclare les paramètres, donc une faute de frappe ici donne un\n  # réglage que personne ne lit plutôt qu'une erreur. Le panneau les montre tels que le moteur\n  # les a annoncés, ce qui est la façon de s'en apercevoir.\n  Cutoff: 1200\n  Res: 0.3\n# En un paragraphe : l'échelle de coupure est logarithmique parce qu'un balayage linéaire en Hz\n# rampe puis s'emballe — la même raison que le `geolerp` de @studio/dsp, ici obtenue en écrivant\n# la course du potard côté panneau. La résonance s'arrête à 0.95 et pas à 1 : au-delà, le filtre\n# entre en oscillation entretenue et le module devient un générateur, ce qui n'est pas ce qu'on\n# vient chercher dans une tranche.\n",
  "audio/filter/sweep/jsdsp.ts":
    '// The DJ filter\'s DSP. The builder arrives as an ARGUMENT, so this file imports nothing at\n// runtime — a song folder has no node_modules and should never need one (the `import type` is\n// erased; see @studio/song\'s dspRunner.mjs).\n//\n// This is @studio/dsp\'s `sweepFilter()` graph, written out here: a module is a FOLDER you can\n// copy, so it carries its own source rather than pointing at a shared library.\n// packages/dsp/src/sweep.test.ts holds the two to the same shape.\n//\n// ONE knob, because a desk control drives at most one param — so "low-pass or high-pass"\n// cannot be a second setting somebody flips. Both filters are therefore always in the chain,\n// and what moves is where each one sits.\n//\n// What makes this a DJ filter rather than a filter is the RESONANCE. A flat corner sliding\n// across a track only muffles it, progressively and dully; the swoosh everyone knows is a PEAK\n// travelling with the corner, lifting a narrow band as it goes. That peak is the effect.\n\nimport type { GraphBuilder } from "@studio/dsp";\n\nexport default (g: GraphBuilder) => {\n  const sweep = g.param("Sweep", { min: -100, max: 100, default: 0 });\n  // -1 .. +1, so the two halves are read off one number by clamping either side of zero.\n  const t = g.mul(sweep, 0.01);\n  const down = g.clamp(g.mul(t, -1), 0, 1);\n  const up = g.clamp(t, 0, 1);\n  // How far from centre, either way. A sum rather than a maximum because only one of the two\n  // is ever non-zero — and the builder has no `max`.\n  const depth = g.add(down, up);\n\n  // Resonance CLIMBS with how far the knob has been pushed: 0.707 is Butterworth, maximally\n  // flat, so a filter doing nothing also colours nothing; 6 whistles. A permanently resonant\n  // filter rings even parked out of the way, and a permanently flat one is a tone control.\n  //\n  // 6 rather than a polite 4, measured: at 4 only about +4 dB was left at the corner once the\n  // flat stage below it had taken its own 3 dB, which is audible but is not what anybody means\n  // by a filter sweep.\n  //\n  // Each half gets its OWN. Sharing one would leave the high-pass ringing at 20 Hz while\n  // somebody sweeps the low-pass down — a resonant peak parked on the sub.\n  const lowQ = g.lerp(0.707, 6, down);\n  const highQ = g.lerp(0.707, 6, up);\n\n  // `glide` on both corners. A biquad recomputes its coefficients per BLOCK, and this is a\n  // knob people throw — a jump between two blocks is a click, and a sweep of them is the\n  // zipper noise that makes a filter sound broken rather than fast.\n  //\n  // At 0 the low-pass sits at 20 kHz and the high-pass at 20 Hz: both outside the material, so\n  // the effect is off by being INAUDIBLE rather than by being bypassed. There is no bypass in\n  // this vocabulary, and a module that must be removed to be silent is one a chain cannot\n  // automate from nothing.\n  //\n  // The low-pass closes to 30 Hz and the high-pass opens to 10 kHz: far enough to take the\n  // track AWAY. A filter that stopped a few hundred hertz down leaves a muddy thump, and the\n  // last part of the sweep — only the peak left whistling — is the part people actually use.\n  // ASCENDING pair, and the journey inverted — never `geolerp(20000, 30, down)`. The engine\n  // sorts a geolerp\'s ends, so a descending pair reads as its own mirror: written the obvious\n  // way this filter sat at 30 Hz at rest and OPENED as you swept, which is silence with the\n  // knob at neutral.\n  const lowHz = g.glide(g.geolerp(30, 20000, g.sub(1, down)));\n  const highHz = g.glide(g.geolerp(20, 10000, up));\n\n  // TWO stages each, so the slope is 24 dB/octave rather than 12. One pole pair muffles; two\n  // is the wall a DJ filter puts up. The first of each pair stays FLAT and only the second\n  // resonates: two resonant stages at one frequency multiply their peaks — Q² — which is a\n  // filter that screams before it sweeps.\n  g.biquad("lowpass", lowHz, 0.707);\n  g.biquad("lowpass", lowHz, lowQ);\n  g.biquad("highpass", highHz, 0.707);\n  g.biquad("highpass", highHz, highQ);\n\n  // …and the trim, LAST, so it takes back a little of what the stages above just added. Only\n  // −3 dB at the extreme: the first attempt took −6 and ate the peak exactly where the peak is\n  // the point, and the clipping it guarded against was theoretical — the filter removes 14 dB\n  // from the whole signal at half sweep. What is left keeps a Q of 6 on a 30 Hz kick from\n  // costing somebody their master.\n  g.gain(g.lerp(1, 0.7, depth));\n};\n',
  "audio/filter/sweep/module.yaml":
    "# Sweep Filter  [audioEffect] — le filtre d'une table de mixage : UN potard, passe-bas vers la\n# gauche, passe-haut vers la droite, transparent au milieu.\n#\n# Un seul paramètre, et ce n'est pas cosmétique : un contrôle du pupitre en pilote au plus un\n# (packages/song/docs/viewBindings.md), donc « passe-bas ou passe-haut » ne peut pas être un\n# second réglage qu'on bascule. Les deux filtres sont donc TOUJOURS dans la chaîne et ce qui\n# bouge est l'endroit où chacun se place — ce qui est aussi le fonctionnement du matériel que\n# ça imite.\n#\n# Sa DSP est décrite dans jsdsp.ts à côté, pas compilée dans le moteur.\nplugin:\n  type: jsdsp\n  name: Sweep Filter\nparams:\n  # 0 est le neutre, au MILIEU de la course : le potard est signé pour que la position de repos\n  # soit au centre plutôt qu'à un bout, comme les gains de l'EQ à côté.\n  Sweep: 0\n# En un paragraphe : un filtre de balayage. Vers la gauche un passe-bas descend de 20 kHz à\n# 200 Hz ; vers la droite un passe-haut monte de 20 Hz à 4 kHz. À 0 les deux coins sont hors du\n# matériel, donc l'effet est éteint parce qu'il est INAUDIBLE et non parce qu'il est contourné —\n# ce qui est ce qui permet de l'automater depuis rien. La résonance est fixe et modeste : un pic\n# qui sonne à 200 Hz reprend la marge de manœuvre en plein set.\n#\n# (C'était un `docs:` ; le champ n'existe plus — voir packages/song/docs/docModules.md.)\n",
  "audio/filter/sweep/ui.yaml":
    "# panel for audio/filter/sweep\n#\n# Un seul potard, et il n'y en aura pas d'autre : la plage et la résonance sont dans la DSP\n# parce que ce sont elles qui font que ce module EST un filtre de table plutôt qu'un filtre\n# générique. Un second bouton ferait un autre module, pas un autre réglage.\n#\n# Signé, donc le neutre tombe exactement au centre de la course — même règle que les gains de\n# l'EQ : un potard dont le repos n'est pas au milieu se lit de travers à chaque coup d'œil.\ncols: 1\nrows: 1\nwidgets:\n  sweep:\n    { type: knob, col: 0, row: 0, label: Filtre, bind: Sweep, min: -100, max: 100, step: 1 }\n",
  "audio/utility/crossfade/jsdsp.json":
    '{\n  "params": [\n    {\n      "name": "Mix",\n      "min": 0,\n      "max": 1,\n      "default": 0.5\n    }\n  ],\n  "nodes": [\n    {\n      "type": "ain",\n      "out": "n0"\n    },\n    {\n      "type": "sub",\n      "in": [1, "Mix"],\n      "out": "n1"\n    },\n    {\n      "type": "amul",\n      "out": "n2",\n      "in": ["n0"],\n      "k": ["n1"]\n    },\n    {\n      "type": "ain",\n      "port": 1,\n      "out": "n3"\n    },\n    {\n      "type": "amul",\n      "out": "n4",\n      "in": ["n3"],\n      "k": ["Mix"]\n    },\n    {\n      "type": "aadd",\n      "out": "n5",\n      "in": ["n2", "n4"]\n    },\n    {\n      "type": "aout",\n      "in": ["n5"]\n    }\n  ]\n}\n',
  "audio/utility/crossfade/jsdsp.ts":
    '// The crossfade\'s DSP. The builder arrives as an ARGUMENT, so this file imports nothing at runtime — a song\n// folder has no node_modules and should never need one (the `import type` is erased; see dspRunner.mjs).\n//\n// `input(0)` and `input(1)` index the ports module.yaml declares, in order: `a` then `b`. An index and not a\n// name, because this graph is compiled to JSON the engine reads with no module.yaml in sight, and position is\n// the one fact both documents can hold on their own.\n//\n// This is @studio/dsp\'s `crossfade()` graph, written out here: a module is a FOLDER you can copy, so it\n// carries its own source rather than pointing at a shared library. packages/dsp/src/crossfade.test.ts holds\n// the two to the same shape.\n\nimport type { GraphBuilder } from "@studio/dsp";\n\nexport default (g: GraphBuilder) => {\n  const mix = g.param("Mix", { min: 0, max: 1, default: 0.5 });\n  // Equal GAIN, not equal power — there is no sqrt among the primitives, and adding one for a single effect\n  // is how a graph language ends up with a node per effect. Linear dips ~3 dB at centre for uncorrelated\n  // material, which is a known shape rather than a bug.\n  const a = g.amul(g.input(0), g.sub(1, mix));\n  const b = g.amul(g.input(1), mix);\n  g.output(g.aadd(a, b));\n};\n',
  "audio/utility/crossfade/module.yaml":
    "# A module that declares its OWN ports, instead of taking the one audio input its type folder\n# would have given it. That is the whole reason a crossfade was unsayable before: `audio/` means\n# one in, one out, and a folder is not the right place to decide how many wires an effect takes.\n#\n# `mandatory: false` on `b`: wiring one side and leaving the other silent is a legitimate state,\n# not a half-built chain. Drop this module into a chain on its own and it plays deck A alone.\n#\n# `plugin: {type: jsdsp}` says the sound comes from the `jsdsp.ts` beside this file — one\n# statement for both facts, so there is no `dsp:` field to keep in step with a plugin name.\nplugin: { type: jsdsp, name: Crossfade }\ninputs:\n  - { name: a, type: audio }\n  - { name: b, type: audio, mandatory: false }\noutputs:\n  - { name: out, type: audio }\nparams:\n  # The graph's own parameter, by its display name — that is how a param finds its plugin\n  # (see applyPluginParams). Centred: both decks at once, which is what makes the demo audible.\n  Mix: 0.5\n# A two-input crossfade. Mix at 0 is deck A alone, at 1 deck B alone, at 0.5 both at half.\n# (Was `docs:`. To say this on the GRAPH, wire this module into a node of `@studio/doc`.)\n",
  "audio/utility/normalize/jsdsp.ts":
    '// The normaliser\'s DSP. The builder arrives as an ARGUMENT, so this file imports nothing at\n// runtime — a song folder has no node_modules and should never need one (the `import type` is\n// erased; see @studio/song\'s dspRunner.mjs).\n//\n// This is @studio/dsp\'s `normalize()` graph, written out here: a module is a FOLDER you can\n// copy, so it carries its own source rather than pointing at a shared library.\n// packages/dsp/src/normalize.test.ts holds the two to the same shape.\n//\n// The graph is four nodes, and that is the point. Applying the gain is trivial; knowing WHICH\n// gain cannot be done here at all — a streaming node sees the samples it has, and the loudest\n// may be the last. So `Peak` is an input, filled in by the pass that reads the file end to end.\n// That is what makes this module cold rather than merely expensive.\n\nimport type { GraphBuilder } from "@studio/dsp";\n\nexport default (g: GraphBuilder) => {\n  const target = g.param("Target", { min: -60, max: 0, default: -1 });\n  const peak = g.param("Peak", { min: -100, max: 0, default: 0 });\n  // Clamped: near silence measures -100 dBFS and would ask for +99 dB, turning hiss into a roar.\n  const gainDb = g.clamp(g.sub(target, peak), -60, 30);\n  g.gain(g.fromdb(gainDb));\n};\n',
  "audio/utility/normalize/module.yaml":
    "# Normalisation — bring the loudest sample of a recording to `Target`.\n#\n# `cold: true` is the load-bearing line. A cold module only works on audio already on disk,\n# because it has to know the WHOLE of its input before it can produce any of it: the gain\n# depends on the peak, and the peak may be the last sample. Adding this to a chain whose\n# signal comes from a live input is refused — see @studio/song's docs/coldModules.md.\n#\n# `plugin: {type: jsdsp}` says the sound comes from the `jsdsp.ts` beside this file, which is\n# @studio/dsp's `normalize()` written out: a module is a FOLDER you can copy, so it carries its\n# own source rather than pointing at a library. packages/dsp/src/normalize.test.ts pins the shape.\ncold: true\nplugin: { type: jsdsp, name: Normalize }\nparams:\n  # 1 dB of headroom, the usual answer for a master.\n  Target: -1\n  # The measured peak of the input, in dBFS, written by the cold pass. 0 until it has run —\n  # which makes the module attenuate rather than boost, the harmless direction to be wrong in.\n  Peak: 0\n# In a paragraph: peak normalisation. Measures the loudest sample of the whole file and applies\n# the gain that puts it at Target. Only works on a file input — live, there is nothing to\n# measure yet. (Was `docs:`; the field is gone, see packages/song/docs/docModules.md.)\n",
  "audio/utility/stemsplit/module.yaml":
    "# Stem separation — one mix in, four stems out, by neural inference on a file.\n#\n# `cold: true` for BOTH reasons the word covers: the answer needs the whole input, and the\n# analysis is affordable once over a file and hopeless per block. Adding it to a chain fed by a\n# live input is refused — see @studio/song's docs/coldModules.md.\n#\n# `plugin: {type: offline}` is the second load-bearing line, and it is what makes four outputs\n# sayable at all. A chain step compiles to a serial insert on one Tracktion track — one buffer\n# in, the same buffer out — so a module that FANS OUT cannot be a plugin. `offline` says there\n# is no engine plugin: a pass writes the outputs to disk before the render. That is why this\n# folder has no jsdsp.ts, unlike its neighbour normalize/.\n#\n# The model is named like any other file-valued param (`onnx:`, exactly as an amp names `nam:`),\n# but 166 MB does not travel through a fork — so `assets/` declares it and the machine's model\n# cache holds the bytes. See @studio/song's docs/moduleAssets.md.\ncold: true\nplugin: { type: offline, name: Stem Split }\n# Four audio outputs, in the order the model returns them. The names are the port names a\n# chains file wires: `stemsplit#vocals: [ reverb ]`.\noutputs:\n  - { name: drums, type: audio }\n  - { name: bass, type: audio }\n  - { name: other, type: audio }\n  - { name: vocals, type: audio }\nparams:\n  # HT-Demucs v4, weights stored fp16. Resolved against this module's assets/ first, then the\n  # machine's ~/.studio/models — which is where a file this size actually lives.\n  onnx: htdemucs_fp16weights.onnx\n# In a paragraph: splits a mix into drums, bass, other and vocals. Runs offline on a file, never\n# live — the model needs the whole input, and one pass takes minutes. The four stems are written\n# as files beside the source, under stems/. (Was `docs:`; see packages/song/docs/docModules.md.)\n",
  "audio/utility/tempo/module.yaml":
    "# Tempo — play a song at a chosen BPM, without moving its pitch.\n#\n# `cold: true` because the answer needs the whole input. A tempo change is a time STRETCH, and\n# a stretch has to know where the file ends to know how far it is being taken; there is no\n# partial answer to give while the audio is still arriving. Adding it to a chain fed by a live\n# input is refused by name — see @studio/song's docs/coldModules.md.\n#\n# `plugin: {type: offline}` because there is no engine plugin to name. The engine hosts a Pitch\n# Shifter (see PluginScan.cpp) and nothing that stretches time: Tracktion does that on a CLIP,\n# through warp markers, not in an insert. So this module is the offline shape — a pass writes\n# the stretched audio to disk before the render — which is also why the folder has no jsdsp.ts.\n# A graph of primitives could not express it either way.\n#\n# The two params mirror normalize/'s `Peak` and `Target`, and for the same reason: one is\n# MEASURED and one is AUTHORED. `Source BPM` is filled in by the pass that reads the file (the\n# same analysis the waveform sidecar carries); `Target BPM` is what a fader sets.\ncold: true\nplugin: { type: offline, name: Tempo }\nparams:\n  # The song's own tempo, written by the pass. 0 means \"not measured yet\", which makes the\n  # module a no-op rather than a stretch by a made-up ratio — the harmless direction to be\n  # wrong in, exactly as normalize's `Peak: 0` attenuates rather than boosts.\n  Source BPM: 0\n  # What to play it at. 0 means \"leave it alone\", so a freshly dropped module changes nothing\n  # until somebody asks for a tempo.\n  Target BPM: 0\n# In a paragraph: plays a song at a chosen tempo. Cold — it stretches a file, so it needs the\n# whole thing, and it runs as a pass rather than live. Pitch is preserved: a record taken faster\n# does not go up in key, unlike a turntable's platter. Both BPM params at 0 is a no-op.\n# (Was `docs:`; the field is gone — see packages/song/docs/docModules.md.)\n",
  "audio/utility/tempo/ui.yaml":
    '# panel for @st0/audio/utility/tempo\n#\n# One knob you turn and one number you read. `Source BPM` is a METER because it is MEASURED,\n# not chosen — the cold pass writes it — exactly as normalize/ draws its `Peak`. Showing it\n# read-only beside the knob is what makes the knob mean something: a target of 128 says\n# nothing until you can see it started at 90.\n#\n# 10..300 covers the tempos that exist, from a dirge to drum-and-bass counted straight. The\n# knob cannot express 0, and 0 is the param\'s default — it is not a tempo, it is the absence\n# of a choice, so an untouched module draws at the floor until the pass measures one or\n# somebody asks for one. Stated here because a knob sitting at its minimum normally means\n# somebody put it there.\ncols: 2\nrows: 2\nwidgets:\n  target:\n    {\n      type: knob,\n      col: 0,\n      row: 0,\n      rowSpan: 2,\n      label: BPM,\n      bind: "Target BPM",\n      min: 10,\n      max: 300,\n      step: 0.1,\n    }\n  source:\n    {\n      type: meter,\n      col: 1,\n      row: 0,\n      rowSpan: 2,\n      label: Source,\n      bind: "Source BPM",\n    }\n',
  "instruments/synth/wurlitzer/dsp.dsp":
    "// dsp.dsp — le Wurlitzer, en Faust : deux paires FM sommées, l'algorithme 5 du TX81Z.\n// Porté depuis `stk::Wurley` (Synthesis ToolKit, CCRMA), dont les nombres sont repris tels\n// quels — voir packages/dsp/docs/wurlitzer.md pour la table de correspondance, les trois\n// écarts assumés et ce qui manque encore pour l'entendre.\n\nimport(\"stdfaust.lib\");\n\n// --- la note ----------------------------------------------------------------\n//\n// Les trois noms que l'enveloppe polyphonique de Faust (`mydsp_poly`) remplit elle-même. Ce\n// ne sont donc PAS des réglages du panneau et ils n'ont rien à faire dans le `params:` du\n// module : ils viennent d'une touche enfoncée, pas d'un potard.\nfreq = hslider(\"freq\", 440, 27.5, 4186, 0.01);\ngain = hslider(\"gain\", 1, 0, 1, 0.01);\ngate = button(\"gate\");\n\n// --- les trois réglages -----------------------------------------------------\n//\n// `control1` et `control2` de STK, sous leurs vrais noms. Les deux valent 1 au repos, ce qui\n// est le réglage d'usine de l'instrument.\nindex = hslider(\"Index\", 1, 0, 2, 0.01); // profondeur de modulation de la paire du corps\ntine = hslider(\"Tine\", 1, 0, 2, 0.01); // combien de la paire d'attaque entre dans le mélange\n// Le vibrato est à ZÉRO au repos, et c'est celui de STK : `modDepth_` vaut 0 tant qu'un\n// contrôleur ne l'ouvre pas. Un Wurlitzer ne vibre pas tout seul.\nvibrato = hslider(\"Vibrato\", 0, 0, 0.5, 0.01);\n\n// --- les briques ------------------------------------------------------------\n\n// La table de gains de STK : `fmGains_[i] = 0.933033 ^ (99 - i)`, donc [99] vaut l'unité.\n// Recalculée plutôt que recopiée — quatre valeurs sur cent, et la formule dit d'où elles viennent.\nfmGain(i) = pow(0.933033, 99 - i);\n\n// Modulation de phase. `m` est en CYCLES et non en radians, comme l'`addPhaseOffset` de STK,\n// pour que les gains ci-dessous se lisent contre le C++ sans conversion à faire de tête.\npm(f, m) = sin(2 * ma.PI * (os.phasor(1.0, f) + m));\n\n// Le deux-zéros de STK, gain 2 : y = 2·(x − x[n−2]). Il adoucit le modulateur d'attaque avant\n// qu'il ne pousse sa porteuse, ce qui est ce qui empêche la frappe de claquer.\ntz(x) = 2.0 * (x - x@2);\n\n// Les quatre enveloppes, `setAllTimes(attaque, chute, tenue, relâche)` de Wurley. La tenue est\n// à zéro pour les quatre : une lame frappée décroît, elle ne se maintient pas — c'est ce qui\n// fait qu'un Wurlitzer est un piano et non un orgue.\ne0 = en.adsr(0.001, 1.50, 0.0, 0.04, gate);\ne1 = en.adsr(0.001, 1.50, 0.0, 0.04, gate);\ne2 = en.adsr(0.001, 0.25, 0.0, 0.04, gate);\ne3 = en.adsr(0.001, 0.15, 0.0, 0.04, gate);\n\nvib = os.osc(8.0) * vibrato;\n\n// --- les deux paires --------------------------------------------------------\n//\n// Paire A, le CORPS : l'opérateur 1 (rapport 4) module l'opérateur 0 (rapport 1). C'est la\n// partie qui suit la note et qui tient une seconde et demie.\nmodA = fmGain(82) * e1 * pm(freq * 4.0, 0);\ncarA = fmGain(99) * e0 * pm(freq, modA * index);\n\n// Paire B, l'ATTAQUE : l'opérateur 3 module l'opérateur 2, et les deux sont à 510 Hz FIXES —\n// un rapport négatif chez STK veut dire une fréquence absolue. D'où le « bark » qui ne\n// transpose pas : le bruit du marteau sur la lame est celui du mécanisme, pas de la note.\nmodB = fmGain(68) * e3 * pm(510.0, vib);\ncarB = fmGain(82) * e2 * pm(510.0, tz(modB));\n\n// Le mélange de STK, y compris le facteur 2 de sortie.\nout = ((1.0 - tine * 0.5) * carA + tine * 0.5 * carB) * 2.0;\n\n// Stéréo par dédoublement : les deux paires sont mono chez STK, et rien ici ne les décorrèle.\n// Élargir serait une décision d'effet, pas de modèle, et elle se prend dans la chaîne.\nprocess = out * gain <: _, _;\n",
  "instruments/synth/wurlitzer/module.yaml":
    "# Wurlitzer [instrument] — le piano électrique à lames : deux paires FM sommées, une qui suit\n# la note et tient, une qui reste à 510 Hz et claque. Porté de `stk::Wurley`.\n#\n# Sa DSP est décrite dans dsp.dsp à côté, en Faust, et c'est le MOTEUR qui la compile.\n#\n# IL NE SONNE PAS ENCORE, et pas parce qu'il serait faux : le moteur n'a pas de compilateur\n# Faust, et un INSTRUMENT demande en plus une couture que la couture Faust n'a pas — MIDI en\n# entrée, un répartiteur de voix, un greffon annoncé comme instrument. Les deux manques sont\n# écrits dans engine/moteur/docs/faust.md ; ce dossier est la source, relisible et complète,\n# qui sera jouée le jour où ils tombent. packages/dsp/docs/wurlitzer.md dit d'où viennent\n# les nombres.\nplugin:\n  type: faust\n  name: Wurlitzer\nparams:\n  # `control1` et `control2` de STK. Ce sont les deux seuls réglages de l'instrument, et ils\n  # valent 1 au repos — le réglage d'usine, pas un neutre choisi ici.\n  Index: 1\n  Tine: 1\n  # À zéro : `modDepth_` de STK vaut zéro tant qu'un contrôleur ne l'ouvre pas.\n  Vibrato: 0\n# En un paragraphe : `freq`, `gain` et `gate` ne sont VOLONTAIREMENT pas dans la liste\n# ci-dessus. Ce sont les trois noms que l'enveloppe polyphonique de Faust remplit à partir des\n# notes reçues, et les inscrire ici en ferait trois potards figés qui écraseraient le jeu —\n# une touche enfoncée n'est pas un réglage. C'est aussi ce qui distingue un instrument d'un\n# effet dans cette écriture, et donc ce qui demande la seconde couture.\n",
};
